/**
 * RADRAFT — Regex PHI Detection
 * Mode: Run Once for All Items
 */

const patterns = {
  SSN: /\b\d{3}-\d{2}-\d{4}\b/g,

  PHONE_EG: /\b(?:\+?20[ -]?|0)1[0125]\d{8}\b/g,

  PHONE_INTL: /\b(?:\+?\d{1,3}[ -]?)?\(?\d{3}\)?[ -]?\d{3}[ -]?\d{4}\b/g,

  NATIONAL_ID_EG: /\b[23]\d{13}\b/g,

  EMAIL: /\b[\w.%+-]+@[\w.-]+\.[A-Za-z]{2,}\b/g,

  MRN: /\bMRN[:# ]?\s?\d{6,10}\b/gi,

  DATE: /\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b/g,

  IP: /\b(?:\d{1,3}\.){3}\d{1,3}\b/g,

  URL: /\bhttps?:\/\/[^\s]+/g,

  ACCOUNT: /\bACCT[:# ]?\s?\d{6,12}\b/gi
};

const output = [];

for (const item of $input.all()) {

  const json = item.json;

  // TopicGuard uses guardrailsInput.
  const text = String(
    json.guardrailsInput ??
    json.chatInput ??
    json.text ??
    json.body?.text ??
    ''
  );

  // Never allow an empty clinical message
  // to proceed to the PHI detection pipeline.
  if (!text.trim()) {
    throw new Error(
      'PHI_GATE_EMPTY_INPUT: No clinical text received.'
    );
  }

  const spans = [];

  for (const [type, pattern] of Object.entries(patterns)) {

    const regex = new RegExp(
      pattern.source,
      pattern.flags
    );

    for (const match of text.matchAll(regex)) {

      spans.push({
        type,
        start: match.index,
        end: match.index + match[0].length,
        value: match[0],
        source: 'regex'
      });

    }
  }

  spans.sort((a, b) =>
    a.start - b.start ||
    b.end - a.end
  );

  output.push({
    json: {
      request_id: String(
        json.request_id ?? $execution.id
      ),
      text,
      spans
    }
  });
}

return output;

/**
 * RADRAFT — CLINICAL PHI DE-IDENTIFICATION
 *
 * Preserves:
 *   userPrompt
 *   mapping
 *   patient_metadata
 *
 * Improvements:
 * - Protects clinical descriptors from false-positive PERSON detection.
 * - Preserves explicitly documented imaging findings.
 * - Masks patient names, DOB, contact details, and identifiers.
 * - Resolves overlapping Presidio detections.
 * - Maintains consistent placeholders.
 * - Fails closed on missing or invalid input.
 *
 * Mode: Run Once for All Items
 */

const text = String(
  $('TopicGuard').first().json.guardrailsInput ?? ''
);

if (!text.trim()) {
  throw new Error('PHI_GATE_EMPTY_INPUT');
}

// Clinical descriptors frequently misclassified as PERSON.
// Only suppress a PERSON detection when it is an exact
// descriptor in a recognized clinical feature field.
const clinicalFields = {
  margins: [
    'smooth',
    'ill-defined',
    'poorly defined',
    'lobulated',
    'irregular',
    'lobulated or irregular',
    'extrathyroidal extension'
  ],
  margin: [
    'smooth',
    'ill-defined',
    'poorly defined',
    'lobulated',
    'irregular',
    'lobulated or irregular',
    'extrathyroidal extension'
  ],
  echogenicity: [
    'anechoic',
    'hyperechoic',
    'isoechoic',
    'hypoechoic',
    'very hypoechoic',
    'heterogeneous'
  ],
  composition: [
    'cystic',
    'almost completely cystic',
    'spongiform',
    'mixed cystic and solid',
    'solid',
    'almost completely solid',
    'solid or almost completely solid'
  ],
  shape: [
    'wider-than-tall',
    'taller-than-wide',
    'wider than tall',
    'taller than wide'
  ],
  'echogenic foci': [
    'none',
    'comet-tail artifacts',
    'macrocalcifications',
    'peripheral calcifications',
    'rim calcifications',
    'punctate echogenic foci'
  ]
};

function normalize(value) {
  return String(value)
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .replace(/[.。;:,]+$/g, '')
    .trim();
}

function isProtectedClinicalDescriptor(start, end) {
  const value = normalize(text.slice(start, end));

  const lineStart = text.lastIndexOf('\n', start - 1) + 1;
  const lineEndIndex = text.indexOf('\n', end);

  const lineEnd = lineEndIndex === -1
    ? text.length
    : lineEndIndex;

  const line = text.slice(lineStart, lineEnd);

  const match = line.match(
    /^\s*([a-zA-Z][a-zA-Z\s-]*?)\s*:\s*(.*?)\s*$/
  );

  if (!match) return false;

  const field = normalize(match[1]);
  const fieldValue = normalize(match[2]);

  const allowed = clinicalFields[field];

  if (!allowed) return false;

  // Must match a recognized clinical descriptor.
  if (!allowed.includes(value)) return false;

  // Only protect the descriptor when it is exactly
  // the value of the recognized clinical field.
  return fieldValue === value;
}

// Read Presidio entities.
let ents = $('Presidio analyze')
  .all()
  .map(item => item.json)
  .flatMap(json => Array.isArray(json) ? json : [json])
  .filter(entity =>
    entity &&
    Number.isInteger(entity.start) &&
    Number.isInteger(entity.end)
  );

// Keep relevant personally identifying entities.
const KEEP = new Set([
  'PERSON',
  'PHONE_NUMBER',
  'EMAIL_ADDRESS',
  'LOCATION',
  'US_SSN',
  'US_PASSPORT',
  'US_DRIVER_LICENSE',
  'IP_ADDRESS'
]);

ents = ents.filter(entity => {
  if (!KEEP.has(entity.entity_type)) return false;

  if (Number(entity.score) < 0.5) return false;

  if (
    entity.entity_type === 'PERSON' &&
    isProtectedClinicalDescriptor(entity.start, entity.end)
  ) {
    return false;
  }

  return true;
});

// Extract explicitly labeled DOB.
const dobRegex =
  /\b(?:date\s+of\s+birth|DOB|birth\s+date)\s*:\s*(\d{1,2}[/-]\d{1,2}[/-]\d{4}|\d{4}-\d{2}-\d{2})/gi;

let patientDOB = null;

for (const match of text.matchAll(dobRegex)) {
  const value = match[1];

  if (patientDOB === null) {
    patientDOB = value;
  } else if (patientDOB !== value) {
    throw new Error(
      'PHI_GATE_AMBIGUOUS_DOB: Multiple different dates of birth.'
    );
  }

  const offset = match[0].lastIndexOf(value);
  const start = match.index + offset;

  ents.push({
    entity_type: 'DOB',
    start,
    end: start + value.length,
    score: 1
  });
}

// Extract explicitly labeled age.
const ageRegex =
  /\b(?:patient\s+age|age)\s*:\s*(\d{1,3})\s*(?:years?|yrs?)?\b/i;

const ageMatch = text.match(ageRegex);

const patientAge = ageMatch
  ? Number(ageMatch[1])
  : null;

if (
  patientAge !== null &&
  (!Number.isInteger(patientAge) ||
   patientAge < 0 ||
   patientAge > 130)
) {
  throw new Error('PHI_GATE_INVALID_AGE');
}

// Add deterministic detections.
function add(regex, entityType) {
  for (const match of text.matchAll(regex)) {
    ents.push({
      entity_type: entityType,
      start: match.index,
      end: match.index + match[0].length,
      score: 1
    });
  }
}

// Egyptian national ID.
add(/\b[23]\d{13}\b/g, 'NATIONAL_ID');

// Medical record number.
add(
  /\bMRN\s*[:#]?\s*\d{5,}\b/gi,
  'MRN_FIELD'
);

// Explicitly labeled patient name.
// Retain PERSON detection even if Presidio missed it.
const patientNameRegex =
  /\b(?:patient\s+name|patient's\s+name)\s*:\s*([^\n\r,;]+)/gi;

for (const match of text.matchAll(patientNameRegex)) {
  const value = match[1].trim();

  if (!value) continue;

  const relativeStart = match[0].lastIndexOf(match[1]);
  const start = match.index + relativeStart;

  ents.push({
    entity_type: 'PERSON',
    start,
    end: start + match[1].length,
    score: 1
  });
}

// Validate entity offsets.
ents = ents.filter(entity =>
  entity.start >= 0 &&
  entity.end <= text.length &&
  entity.end > entity.start
);

// Resolve overlaps using confidence and length.
ents.sort((a, b) =>
  Number(b.score) - Number(a.score) ||
  (b.end - b.start) - (a.end - a.start)
);

const kept = [];

for (const entity of ents) {
  const overlaps = kept.some(existing =>
    entity.start < existing.end &&
    entity.end > existing.start
  );

  if (!overlaps) {
    kept.push(entity);
  }
}

kept.sort((a, b) => a.start - b.start);

// Replace PHI with placeholders.
let output = '';
let cursor = 0;

const mapping = {};
const counters = {};
const seen = {};

for (const entity of kept) {
  const value = text.slice(entity.start, entity.end);

  const type = entity.entity_type === 'MRN_FIELD'
    ? 'MRN'
    : entity.entity_type;

  const key = type + '|' + value.toLowerCase();

  if (!seen[key]) {
    counters[type] = (counters[type] || 0) + 1;

    const placeholder = `[${type}_${counters[type]}]`;

    seen[key] = placeholder;
    mapping[placeholder] = value;
  }

  output += text.slice(cursor, entity.start);
  output += seen[key];

  cursor = entity.end;
}

output += text.slice(cursor);

// Preserve the original output contract.
return [{
  json: {
    userPrompt: output,
    mapping,
    patient_metadata: {
      date_of_birth: patientDOB,
      stated_age: patientAge
    }
  }
}];
